// #162455 (6a993d701197515dfc162455) «פיתוח: מסך פתיחה והנחיות למועמד» — проверено 04.11.2026, «עבר QA» 04.11.
//  - AC2 / реджект 2: на «איך זה עובד» — «השיחה תתקיים עם בינה מלאכותית ( AI ) ולא מול אדם»; AC4 — без горизонтальной
//    прокрутки на 390 и 1440 (скрины 162455-ai-disclosure-390/-desktop/-pixel6.png);
//  - реджект 1: сбой загрузки ссылки (candidate_open_link оборван) → «לא הצלחנו לטעון את הסימולציה…», «טעינת המסך לא
//    צורכת את הניסיון הרשמי…» и «לנסות שוב» (скрин 162455-load-error-390.png); AC5 — «?» на экране ошибки.
// НЕ prod-safe: каждый тест создаёт кандидата «QA-AUTO-162455-…» (business, link_only — без письма/SMS), не удаляется
// (удаления кандидатов нет) → @data. Звонок не начинается (blockCallStarts).
import { test, expect } from '../../fixtures';
import { runStamp } from '../support/api';
import { blockCallStarts } from './support';
import { A11Y, newCandidateLink, tapBtn } from './a11y-support';
import { helpEntry, noHorizontalScroll, openWelcome } from './help-1104-support';

const HASH = '#162455 · #6a993d701197515dfc162455';
const AI_DISCLOSURE = 'השיחה תתקיים עם בינה מלאכותית ( AI ) ולא מול אדם';
const LOAD = {
  error: 'לא הצלחנו לטעון את הסימולציה. בדקו את החיבור לאינטרנט ונסו שוב.',
  official: 'טעינת המסך לא צורכת את הניסיון הרשמי',
  retry: 'לנסות שוב',
};

test.describe(`Кандидат — экран открытия: AI-раскрытие и ошибка загрузки (${HASH})`, () => {
  test(`«איך זה עובד»: «${AI_DISCLOSURE}», без горизонтальной прокрутки, «?» на экране @mobile @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-162455-M-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (только экраны открытия), не удаляется` });
    const blocked = await blockCallStarts(page);

    await openWelcome(page, link);
    await tapBtn(page, A11Y.welcomeCta);
    await expect(page.getByText('איך זה עובד').first()).toBeVisible();
    await expect(page.getByRole('button', { name: A11Y.howCta })).toBeVisible();

    // Источник: AC2 «הבהרה שהשיחה מתנהלת מול AI ולא מול אדם»; AC4 «ללא גלילה אופקית».
    await expect(page.getByText(AI_DISCLOSURE)).toBeVisible();
    await noHorizontalScroll(page, 'איך זה עובד');
    // Источник: AC5 «בכל מסך קישור לפנייה לגורם אנושי».
    await expect(helpEntry(page)).toBeVisible();
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });

  test(`390 и 1440: «${AI_DISCLOSURE}» на «איך זה עובד», без горизонтальной прокрутки @desktop @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-162455-D-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (только экраны открытия), не удаляется` });
    const blocked = await blockCallStarts(page);

    await openWelcome(page, link);
    await tapBtn(page, A11Y.welcomeCta);
    await expect(page.getByRole('button', { name: A11Y.howCta })).toBeVisible();
    for (const w of [390, 1440]) {
      await page.setViewportSize({ width: w, height: w < 768 ? 844 : 900 });
      // Источник: AC2 + ответ программиста 02.11 (блок ai-disclosure); AC4.
      await expect(page.getByText(AI_DISCLOSURE), `@${w}`).toBeVisible();
      await noHorizontalScroll(page, `איך זה עובד @${w}`);
    }
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });

  test(`сбой загрузки ссылки (candidate_open_link оборван) → «${LOAD.error}», «${LOAD.official}…», «${LOAD.retry}», «?»; сеть вернулась → «בוא נתחיל» @mobile @data ${HASH}`, async ({ browser, page, baseURL }, testInfo) => {
    test.setTimeout(3 * 60_000);
    const name = `QA-AUTO-162455-E-${runStamp()}`;
    const link = await newCandidateLink(browser, name, baseURL!);
    testInfo.annotations.push({ type: 'test-data', description: `кандидат «${name}» (ссылка открыта после ошибки загрузки), не удаляется` });
    const blocked = await blockCallStarts(page);

    let aborted = 0;
    const OPEN = '**/rest/v1/rpc/candidate_open_link';
    await page.route(OPEN, (r) => {
      aborted++;
      return r.abort('failed');
    });
    await page.goto(link);

    // Источник: реджект 1 (13.10) — ошибка загрузки объясняет, что официальная попытка не начата и не израсходована.
    await expect(page.getByText(LOAD.error)).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(new RegExp(`${LOAD.official}`))).toBeVisible();
    await expect(page.getByText(/הוא לא מתחיל עד שתתחילו את השיחה הרשמית בעצמכם/)).toBeVisible();
    await expect(page.getByRole('button', { name: LOAD.retry })).toBeVisible();
    await expect(helpEntry(page)).toBeVisible(); // AC5
    await noHorizontalScroll(page, 'ошибка загрузки');
    expect(aborted, 'candidate_open_link не вызывался').toBeGreaterThan(0);

    await page.unroute(OPEN);
    await page.getByRole('button', { name: LOAD.retry }).click();
    await expect(page.getByRole('button', { name: A11Y.welcomeCta })).toBeVisible({ timeout: 30_000 });
    await expect(page.getByText(LOAD.error)).toHaveCount(0);
    expect(blocked.start + blocked.voice, 'старт попытки').toBe(0);
  });
});
